from rdkit import Chem
from rdkit.Chem import AllChem
rw=Chem.RWMol(); idx={}
def atom(name,el,charge=0):
 a=Chem.Atom(el); a.SetFormalCharge(charge); i=rw.AddAtom(a); idx[name]=i; return i
def bond(a,b,t=Chem.BondType.SINGLE): rw.AddBond(idx[a],idx[b],t)
def phenyl(prefix, attach, subs=()):
 # ring sequential C0...5, attach is atom name of substituent bond at ring carbon 0; substitution dict ring index->name
 names=[prefix+str(i) for i in range(6)]
 for n in names: atom(n,'C')
 for i in range(6): bond(names[i],names[(i+1)%6],Chem.BondType.AROMATIC)
 for n in names: rw.GetAtomWithIdx(idx[n]).SetIsAromatic(True)
 for i in range(6): rw.GetBondBetweenAtoms(idx[names[i]],idx[names[(i+1)%6]]).SetIsAromatic(True)
 bond(attach,names[0])
 for k,sub in subs:
  atom(sub,'C'); bond(names[k],sub)
 return names
# skeleton main
atom('N','N'); atom('P','P',1); atom('Ge','Ge'); atom('IrA','Ir'); atom('IrB','Ir'); atom('ClA','Cl'); atom('ClB','Cl'); atom('ClC','Cl')
# central ring covalent main links
bond('N','Ge'); bond('Ge','IrB'); bond('IrB','IrA'); bond('N','P'); bond('Ge','ClA'); bond('Ge','ClB'); bond('IrB','ClC')
# DIPP phenyl at N, iPr at ring positions 2,6
phenyl('Ar','N',[(2,'iC1'),(4,'iC2')])
# add methyls for isopropyls
for n in ['iC1','iC2']:
 for suffix in ['a','b']:
  m=n+suffix; atom(m,'C'); bond(n,m)
# two phenyl groups on P
phenyl('Ph1','P'); phenyl('Ph2','P')
# dative P -> IrA
rw.AddBond(idx['P'],idx['IrA'],Chem.BondType.DATIVE)
# CODs each 8 ring, 1,5 diene, metal bound at alkene C 1 and C5
for pref,metal in [('Top','IrA'),('Bot','IrB')]:
 names=[pref+str(i+1) for i in range(8)]
 for n in names: atom(n,'C')
 for j in range(8):
  btype=Chem.BondType.DOUBLE if j in (0,4) else Chem.BondType.SINGLE
  bond(names[j],names[(j+1)%8],btype)
 for j in (0,4):
  rw.AddBond(idx[names[j]],idx[metal],Chem.BondType.DATIVE)
m=rw.GetMol()
try:
 Chem.SanitizeMol(m)
 print('sanitized',m.GetNumAtoms())
except Exception as e:
 print('sanitize err',e)
 raise
m=Chem.AddHs(m)
print('atoms',m.GetNumAtoms())
params=AllChem.ETKDGv3(); params.randomSeed=23; params.maxIterations=1000
res=AllChem.EmbedMolecule(m,params)
print('embed',res)
if res<0:
 for s in range(10):
  params.randomSeed=s+1; res=AllChem.EmbedMolecule(m,params); print(s,res)
  if res==0: break
if res<0: exit()
AllChem.MMFFOptimizeMolecule(m,maxIters=500)
conf=m.GetConformer()
with open('initial.xyz','w') as f:
 f.write(f'{m.GetNumAtoms()}\ninitial\n')
 for a in m.GetAtoms():
  p=conf.GetAtomPosition(a.GetIdx()); f.write(f'{a.GetSymbol()} {p.x:.6f} {p.y:.6f} {p.z:.6f}\n')
# dump key centers
for n in ['N','P','Ge','IrA','IrB','ClA','ClB','ClC','Top1','Top2','Top5','Top6','Bot1','Bot2','Bot5','Bot6']:
 p=conf.GetAtomPosition(idx[n]); print(n,tuple(round(x,2) for x in p))
